// Validate input and extract batch data
const inputData = $input.first().json;
const requestData = inputData.body || inputData;

try {
  // Validate required fields
  if (!requestData.batchId) {
    throw new Error('batchId is required');
  }

  console.log(`Processing deduplication for batch ${requestData.batchId}`);

  // In production, fetch properties from database using batchId
  // For demo, generate sample properties
  const properties = [];

  // Simulate fetching 50 properties (some will be duplicates)
  for (let i = 0; i < 50; i++) {
    const isDuplicate = i > 30 && Math.random() > 0.5;
    const baseIndex = isDuplicate ? Math.floor(Math.random() * 30) : i;

    properties.push({
      id: `prop-${i}`,
      address: isDuplicate ? `${1000 + baseIndex} Main St` : `${1000 + i} ${['Main', 'Oak', 'Elm'][i % 3]} St`,
      city: 'Austin',
      state: 'TX',
      zipCode: isDuplicate ? String(78701 + (baseIndex % 10)) : String(78701 + (i % 10)),
      latitude: isDuplicate ? 30.2672 + (baseIndex * 0.001) : 30.2672 + (i * 0.001),
      longitude: isDuplicate ? -97.7431 + (baseIndex * 0.001) : -97.7431 + (i * 0.001),
      ownerName: isDuplicate ? `Owner ${baseIndex} LLC` : `Owner ${i} LLC`,
      listPrice: 1000000 + (i * 50000),
      squareFeet: 10000 + (i * 500),
      source: ['LoopNet', 'CoStar', 'Crexi'][i % 3],
      parcelId: isDuplicate ? `PARC-${baseIndex}` : (Math.random() > 0.7 ? `PARC-${i}` : null)
    });
  }

  return [{
    json: {
      batchId: requestData.batchId,
      properties: properties,
      totalCount: properties.length,
      timestamp: new Date().toISOString()
    }
  }];

} catch (error) {
  console.error('Validation error:', error.message);
  throw error;
}

// Advanced deduplication algorithm
const data = $input.first().json;
const properties = data.properties;

console.log(`Starting deduplication on ${properties.length} properties`);

// Normalize addresses for comparison
function normalizeAddress(address) {
  return address
    .toUpperCase()
    .replace(/\bSTREET\b/g, 'ST')
    .replace(/\bAVENUE\b/g, 'AVE')
    .replace(/\bROAD\b/g, 'RD')
    .replace(/\bBOULEVARD\b/g, 'BLVD')
    .replace(/[^A-Z0-9]/g, '');
}

// Calculate Levenshtein distance for fuzzy matching
function levenshteinDistance(str1, str2) {
  const matrix = [];

  for (let i = 0; i <= str2.length; i++) {
    matrix[i] = [i];
  }

  for (let j = 0; j <= str1.length; j++) {
    matrix[0][j] = j;
  }

  for (let i = 1; i <= str2.length; i++) {
    for (let j = 1; j <= str1.length; j++) {
      if (str2.charAt(i - 1) === str1.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1,
          matrix[i][j - 1] + 1,
          matrix[i - 1][j] + 1
        );
      }
    }
  }

  return matrix[str2.length][str1.length];
}

// Calculate geographic distance (Haversine formula)
function calculateDistance(lat1, lon1, lat2, lon2) {
  const R = 6371; // Earth's radius in km
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;

  const a = 
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) * Math.sin(dLon / 2);

  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  const distance = R * c * 1000; // Convert to meters

  return distance;
}

// Deduplication matching function
function calculateMatchScore(prop1, prop2) {
  let score = 0;
  let confidence = 0;
  const reasons = [];

  // 1. Exact parcel ID match (highest confidence)
  if (prop1.parcelId && prop2.parcelId && prop1.parcelId === prop2.parcelId) {
    score += 100;
    confidence = 100;
    reasons.push('Exact parcel ID match');
    return { score, confidence, reasons };
  }

  // 2. Address matching
  const addr1 = normalizeAddress(`${prop1.address}${prop1.zipCode}`);
  const addr2 = normalizeAddress(`${prop2.address}${prop2.zipCode}`);

  if (addr1 === addr2) {
    score += 50;
    confidence = 95;
    reasons.push('Exact address match');
  } else {
    const distance = levenshteinDistance(addr1, addr2);
    const similarity = 1 - (distance / Math.max(addr1.length, addr2.length));

    if (similarity > 0.9) {
      score += 40;
      confidence = Math.max(confidence, 85);
      reasons.push(`High address similarity (${(similarity * 100).toFixed(1)}%)`);
    }
  }

  // 3. Geographic proximity
  if (prop1.latitude && prop2.latitude) {
    const distance = calculateDistance(
      prop1.latitude, prop1.longitude,
      prop2.latitude, prop2.longitude
    );

    if (distance < 30) { // Within 30 meters
      score += 30;
      confidence = Math.max(confidence, 85);
      reasons.push(`Same location (${distance.toFixed(1)}m apart)`);
    } else if (distance < 100) {
      score += 15;
      confidence = Math.max(confidence, 70);
      reasons.push(`Close proximity (${distance.toFixed(1)}m apart)`);
    }
  }

  // 4. Owner name matching
  const owner1 = normalizeAddress(prop1.ownerName || '');
  const owner2 = normalizeAddress(prop2.ownerName || '');

  if (owner1 && owner2 && owner1 === owner2) {
    score += 20;
    reasons.push('Same owner');
  }

  // Final confidence calculation
  if (score >= 80) {
    confidence = Math.max(confidence, 95);
  } else if (score >= 60) {
    confidence = Math.max(confidence, 80);
  } else if (score >= 40) {
    confidence = Math.max(confidence, 60);
  }

  return { score, confidence, reasons };
}

// Group duplicates
const duplicateGroups = [];
const processed = new Set();

for (let i = 0; i < properties.length; i++) {
  if (processed.has(i)) continue;

  const group = {
    master: properties[i],
    duplicates: [],
    groupId: `group-${duplicateGroups.length + 1}`
  };

  processed.add(i);

  for (let j = i + 1; j < properties.length; j++) {
    if (processed.has(j)) continue;

    const match = calculateMatchScore(properties[i], properties[j]);

    if (match.confidence >= 70) {
      group.duplicates.push({
        property: properties[j],
        matchScore: match.score,
        confidence: match.confidence,
        reasons: match.reasons
      });
      processed.add(j);
    }
  }

  duplicateGroups.push(group);
}

// Merge duplicate data (take best data from each duplicate)
const deduplicatedProperties = duplicateGroups.map(group => {
  const merged = { ...group.master };

  // Prefer properties with more complete data
  group.duplicates.forEach(dup => {
    Object.keys(dup.property).forEach(key => {
      if (!merged[key] && dup.property[key]) {
        merged[key] = dup.property[key];
      }
    });
  });

  merged.isDeduplicated = group.duplicates.length > 0;
  merged.duplicateCount = group.duplicates.length;
  merged.groupId = group.groupId;
  merged.sources = [merged.source, ...group.duplicates.map(d => d.property.source)];

  return merged;
});

const stats = {
  totalInput: properties.length,
  totalOutput: deduplicatedProperties.length,
  duplicatesRemoved: properties.length - deduplicatedProperties.length,
  deduplicationRate: (((properties.length - deduplicatedProperties.length) / properties.length) * 100).toFixed(2) + '%'
};

console.log('Deduplication complete:', stats);

return [{
  json: {
    batchId: data.batchId,
    properties: deduplicatedProperties,
    statistics: stats,
    timestamp: new Date().toISOString()
  }
}];

// Owner entity resolution
// Chain: Property → LLC → Registered Agent → Parent Company → Key Person

const data = $input.first().json;
const properties = data.properties;

console.log(`Resolving entities for ${properties.length} properties`);

// Simulate entity resolution (in production, call Secretary of State APIs)
const resolvedProperties = properties.map(prop => {
  const ownerLLC = prop.ownerName;

  // Simulate LLC lookup
  const entityResolution = {
    llcName: ownerLLC,
    registeredAgent: `Agent Services Inc`,
    registeredState: prop.state,
    parentCompany: Math.random() > 0.5 ? `${ownerLLC.replace(' LLC', '')} Holdings` : null,
    keyPerson: {
      name: `${['John', 'Jane', 'Michael', 'Sarah'][Math.floor(Math.random() * 4)]} ${['Smith', 'Johnson', 'Williams'][Math.floor(Math.random() * 3)]}`,
      title: ['CEO', 'Managing Partner', 'President', 'Owner'][Math.floor(Math.random() * 4)],
      confidence: Math.floor(Math.random() * 30) + 70
    },
    businessAddress: `${prop.address}, ${prop.city}, ${prop.state}`,
    filingDate: new Date(Date.now() - Math.floor(Math.random() * 365 * 5) * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    entityType: 'LLC',
    status: 'Active'
  };

  return {
    ...prop,
    entityResolution: entityResolution,
    entityResolved: true,
    hasKeyPerson: true
  };
});

console.log(`Resolved entities for ${resolvedProperties.length} properties`);

return [{
  json: {
    batchId: data.batchId,
    properties: resolvedProperties,
    statistics: data.statistics,
    timestamp: new Date().toISOString()
  }
}];

// Financial modeling and calculations
const data = $input.first().json;
const properties = data.properties;

console.log(`Calculating financial models for ${properties.length} properties`);

const propertiesWithFinancials = properties.map(prop => {
  // Calculate or refine financial metrics
  const listPrice = prop.listPrice;
  const squareFeet = prop.squareFeet;
  const estimatedNOI = listPrice * (Math.random() * 0.05 + 0.06); // 6-11% NOI

  // Cap Rate
  const capRate = ((estimatedNOI / listPrice) * 100).toFixed(2);

  // Assume 75% LTV financing at 6.5% interest
  const loanAmount = listPrice * 0.75;
  const downPayment = listPrice * 0.25;
  const interestRate = 0.065;
  const loanTerm = 30;

  // Monthly payment calculation
  const monthlyRate = interestRate / 12;
  const numPayments = loanTerm * 12;
  const monthlyPayment = loanAmount * (monthlyRate * Math.pow(1 + monthlyRate, numPayments)) / (Math.pow(1 + monthlyRate, numPayments) - 1);
  const annualDebtService = monthlyPayment * 12;

  // Cash Flow
  const annualCashFlow = estimatedNOI - annualDebtService;
  const cashOnCashReturn = ((annualCashFlow / downPayment) * 100).toFixed(2);

  // DSCR (Debt Service Coverage Ratio)
  const dscr = (estimatedNOI / annualDebtService).toFixed(2);

  // Price per square foot
  const pricePerSqFt = Math.round(listPrice / squareFeet);

  // IRR projection (simplified)
  const projectedAppreciation = 0.03; // 3% annual appreciation
  const projectedYear5Value = listPrice * Math.pow(1 + projectedAppreciation, 5);
  const totalCashFlow5Years = annualCashFlow * 5;
  const totalReturn = (projectedYear5Value - listPrice + totalCashFlow5Years);
  const irr = ((Math.pow(totalReturn / downPayment, 1/5) - 1) * 100).toFixed(2);

  const financialModel = {
    // Core metrics
    listPrice: listPrice,
    estimatedNOI: Math.round(estimatedNOI),
    capRate: parseFloat(capRate),
    pricePerSqFt: pricePerSqFt,

    // Financing
    loanAmount: Math.round(loanAmount),
    downPayment: Math.round(downPayment),
    interestRate: interestRate,
    monthlyPayment: Math.round(monthlyPayment),
    annualDebtService: Math.round(annualDebtService),

    // Returns
    annualCashFlow: Math.round(annualCashFlow),
    cashOnCashReturn: parseFloat(cashOnCashReturn),
    dscr: parseFloat(dscr),
    projectedIRR: parseFloat(irr),

    // Projections
    year5Value: Math.round(projectedYear5Value),
    totalReturn5Year: Math.round(totalReturn),

    // Investment quality indicators
    meetsCapRateMin: parseFloat(capRate) >= 7,
    meetsDSCRMin: parseFloat(dscr) >= 1.25,
    meetsIRRMin: parseFloat(irr) >= 15
  };

  return {
    ...prop,
    financialModel: financialModel,
    financialsCalculated: true
  };
});

console.log(`Financial modeling complete for ${propertiesWithFinancials.length} properties`);

return [{
  json: {
    batchId: data.batchId,
    properties: propertiesWithFinancials,
    statistics: data.statistics,
    timestamp: new Date().toISOString()
  }
}];

// Market comparables analysis
const data = $input.first().json;
const properties = data.properties;

console.log(`Running comparable analysis for ${properties.length} properties`);

// Group properties by city and property type for comparison
const groupedProperties = {};

properties.forEach(prop => {
  const key = `${prop.city}-${prop.propertyType || 'unknown'}`;
  if (!groupedProperties[key]) {
    groupedProperties[key] = [];
  }
  groupedProperties[key].push(prop);
});

// Calculate market statistics for each group
const propertiesWithComps = properties.map(prop => {
  const key = `${prop.city}-${prop.propertyType || 'unknown'}`;
  const comparables = groupedProperties[key] || [];

  if (comparables.length < 2) {
    return {
      ...prop,
      marketComparables: {
        available: false,
        message: 'Insufficient comparable properties'
      }
    };
  }

  // Calculate market statistics
  const prices = comparables.map(p => p.listPrice);
  const capRates = comparables.map(p => p.financialModel?.capRate || 0).filter(r => r > 0);
  const pricesPerSqFt = comparables.map(p => p.financialModel?.pricePerSqFt || 0).filter(p => p > 0);

  const median = arr => {
    const sorted = [...arr].sort((a, b) => a - b);
    const mid = Math.floor(sorted.length / 2);
    return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
  };

  const average = arr => arr.reduce((sum, val) => sum + val, 0) / arr.length;

  const marketStats = {
    available: true,
    comparableCount: comparables.length,
    medianPrice: Math.round(median(prices)),
    averagePrice: Math.round(average(prices)),
    medianCapRate: capRates.length > 0 ? parseFloat(median(capRates).toFixed(2)) : null,
    medianPricePerSqFt: pricesPerSqFt.length > 0 ? Math.round(median(pricesPerSqFt)) : null,

    // Relative positioning
    priceVsMarket: ((prop.listPrice / median(prices) - 1) * 100).toFixed(2) + '%',
    capRateVsMarket: prop.financialModel?.capRate && capRates.length > 0 
      ? ((prop.financialModel.capRate / median(capRates) - 1) * 100).toFixed(2) + '%'
      : null,

    // Value assessment
    isPricedBelowMarket: prop.listPrice < median(prices),
    isCapRateAboveMarket: prop.financialModel?.capRate && capRates.length > 0 
      ? prop.financialModel.capRate > median(capRates)
      : null
  };

  return {
    ...prop,
    marketComparables: marketStats
  };
});

console.log(`Market analysis complete for ${propertiesWithComps.length} properties`);

return [{
  json: {
    batchId: data.batchId,
    properties: propertiesWithComps,
    statistics: data.statistics,
    processingComplete: true,
    timestamp: new Date().toISOString()
  }
}];

// Save processed properties to database
const data = $input.first().json;

console.log(`[DATABASE] Saving ${data.properties.length} processed properties`);

// In production, write to PostgreSQL
const result = {
  success: true,
  batchId: data.batchId,
  recordsProcessed: data.properties.length,
  statistics: data.statistics,
  timestamp: new Date().toISOString(),
  nextStep: 'enrichment-layer'
};

return [{ json: result }];
